// src/store/locationStore.js — Locations: paged / filtered / sorted server-side (generated by make:module).

import { create } from 'zustand';
import locationApi from '../services/locations/locationApi';

export const DEFAULT_LOCATIONS_PARAMS = { page: 1, per_page: 20, search: '', type: undefined, active: undefined, sort: undefined, order: undefined };

const useLocationStore = create((set, get) => ({

  // ── State ──────────────────────────────────────────
  items:     [],
  total:     0,
  params:    DEFAULT_LOCATIONS_PARAMS,
  isLoading: false,
  error:     null,

  // ── Actions ────────────────────────────────────────
  fetchItems: async (changes = {}) => {
    const params = { ...get().params, ...changes };
    set({ params, isLoading: true, error: null });
    try {
      const { data } = await locationApi.getAll(params);
      set({ items: data.data, total: data.meta.total });
    } catch (error) {
      set({ error: error.response?.data?.message || 'Failed to load locations.' });
    } finally {
      set({ isLoading: false });
    }
  },

}));

export default useLocationStore;
